solution.javascript:
function longueurCouplet(n, memo = {}) {
  if (n <= 2) {
    return n + 1;
  }
  if (!(n in memo)) {
    memo[n] = longueurCouplet(n - 1, memo) + longueurCouplet(n - 2, memo);
  }
  return memo[n];
}

solution.python:
def longueur_couplet(n, memo=None):
    if memo is None:
        memo = {}
    if n <= 2:
        return n + 1
    if n not in memo:
        memo[n] = longueur_couplet(n - 1, memo) + longueur_couplet(n - 2, memo)
    return memo[n]

