function compterMontees(nbMarches, interdites) {
  const bloquees = new Set(interdites);
  const facons = new Array(nbMarches + 1).fill(0);
  facons[0] = 1;
  for (let k = 1; k <= nbMarches; k++) {
    if (bloquees.has(k)) {
      continue;
    }
    for (let bond = 1; bond <= 3; bond++) {
      if (k - bond >= 0) {
        facons[k] += facons[k - bond];
      }
    }
  }
  return facons[nbMarches];
}

solution.python:
def compter_montees(nb_marches, interdites):
    bloquees = set(interdites)
    facons = [0] * (nb_marches + 1)
    facons[0] = 1
    for k in range(1, nb_marches + 1):
        if k in bloquees:
            continue
        for bond in (1, 2, 3):
            if k - bond >= 0:
                facons[k] += facons[k - bond]
    return facons[nb_marches]

