solution.javascript:
function compterRefrains(couplet, refrain) {
  const n = couplet.length;
  const m = refrain.length;
  // facons[i][j] : façons de former les j premières lettres du refrain avec les i premières du couplet
  const facons = [];
  for (let i = 0; i <= n; i++) {
    facons.push(new Array(m + 1).fill(0));
    facons[i][0] = 1;
  }
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      facons[i][j] = facons[i - 1][j];
      if (couplet[i - 1] === refrain[j - 1]) {
        facons[i][j] += facons[i - 1][j - 1];
      }
    }
  }
  return facons[n][m];
}

solution.python:
def compter_refrains(couplet, refrain):
    n = len(couplet)
    m = len(refrain)
    # facons[i][j] : façons de former les j premières lettres du refrain avec les i premières du couplet
    facons = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        facons[i][0] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            facons[i][j] = facons[i - 1][j]
            if couplet[i - 1] == refrain[j - 1]:
                facons[i][j] += facons[i - 1][j - 1]
    return facons[n][m]

